import { eventBus } from "@/main";

const BASE_EXT = "http://ihris.org/fhir/StructureDefinition/";

export default {
  name: "CreatePosition",
  mixins: [processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/position",
      fhir: {},
      fhirId: "",
      profile: "http://ihris.org/fhir/StructureDefinition/position-profile",
      isEdit: true,
      valid: false,
      saving: false,
      prefillReady: true,
      snackbar: { show: false, text: "", color: "success" },

      form: {
        name: "",
        code: "",
        designation: "",
        grade: "",
        department: "",
        facility: "",
        maximumPractitioners: "",
        status: "",
        description: "",
        comments: "",
      },

      specifications: [
        {
          groupOperator: "",
          qualificationCriteria: [],
          experienceCriteria: [],
          otherRequirements: [],
        },
      ],
    };
  },

  computed: {
    editMode() {
      return !!(this.queries && this.queries.id);
    },
  },

  methods: {
    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    // ── Helpers ──────────────────────────────────────────────────────
    getRef(val) {
      if (!val) return null;
      if (typeof val === "string") return val;
      return val.reference || null;
    },

    parseCoding(val) {
      if (!val) return null;
      if (typeof val === "object") return val;
      const idx = val.lastIndexOf("#");
      if (idx === -1) return { code: val };
      return { system: val.slice(0, idx), code: val.slice(idx + 1) };
    },

    getCriterionOpLabel(val) {
      if (!val) return "AND";
      const code = typeof val === "string" ? val.split("#").pop() : val.code;
      return code === "or" ? "OR" : "AND";
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    goBack() {
      if (this.editMode) {
        this.$router.push({
          path: "/custom/view-position",
          query: { path: "/lesotho/components/position", id: this.queries.id },
        });
      } else {
        this.$router.push({
          path: "/custom/index",
          query: { path: "/lesotho/components/position" },
        });
      }
    },

    // ── EventBus registrations ────────────────────────────────────────
    registerSpecListeners(si) {
      eventBus.$on(`Basic.spec[${si}].group-op`, (val) => {
        if (this.specifications[si])
          this.specifications[si].groupOperator = val;
      });
    },

    registerQualCritListeners(si, ci) {
      eventBus.$on(`Basic.spec[${si}].qual-crit[${ci}].level`, (val) => {
        const row =
          this.specifications[si] &&
          this.specifications[si].qualificationCriteria[ci];
        if (row !== undefined)
          this.specifications[si].qualificationCriteria[
            ci
          ].qualificationLevel = val;
      });
      eventBus.$on(`Basic.spec[${si}].qual-crit[${ci}].name`, (val) => {
        if (val === "Basic/otherqualificationname") {
          this.showSnackbar(
            '"Other" is not a valid qualification name selection.',
            "error",
          );
          // Remount the fhir-reference by bumping its key, which resets its
          // internal select/display back to empty without saving the value.
          const crit = this.specifications[si]?.qualificationCriteria[ci];
          if (crit !== undefined) {
            this.$set(crit, "nameKey", (crit.nameKey || 0) + 1);
          }
          return;
        }
        const row =
          this.specifications[si] &&
          this.specifications[si].qualificationCriteria[ci];
        if (row !== undefined)
          this.specifications[si].qualificationCriteria[
            ci
          ].qualificationName = { reference: val };
      });
      eventBus.$on(`Basic.spec[${si}].qual-crit[${ci}].op`, (val) => {
        const row =
          this.specifications[si] &&
          this.specifications[si].qualificationCriteria[ci];
        if (row !== undefined)
          this.specifications[si].qualificationCriteria[
            ci
          ].criterionOperator = val;
      });
    },

    registerExpCritListeners(si, ci) {
      eventBus.$on(`Basic.spec[${si}].exp-crit[${ci}].years`, (val) => {
        const row =
          this.specifications[si] &&
          this.specifications[si].experienceCriteria[ci];
        if (row !== undefined)
          this.specifications[si].experienceCriteria[ci].minimumYears = val;
      });
      eventBus.$on(`Basic.spec[${si}].exp-crit[${ci}].title`, (val) => {
        const row =
          this.specifications[si] &&
          this.specifications[si].experienceCriteria[ci];
        if (row !== undefined)
          this.specifications[si].experienceCriteria[ci].jobTitle = val;
      });
      eventBus.$on(`Basic.spec[${si}].exp-crit[${ci}].op`, (val) => {
        const row =
          this.specifications[si] &&
          this.specifications[si].experienceCriteria[ci];
        if (row !== undefined)
          this.specifications[si].experienceCriteria[
            ci
          ].criterionOperator = val;
      });
    },

    registerOtherReqListener(si, ri) {
      eventBus.$on(`Basic.spec[${si}].other[${ri}]`, (val) => {
        if (this.specifications[si]) {
          this.$set(this.specifications[si].otherRequirements, ri, val);
        }
      });
    },

    // ── Spec builder operations ───────────────────────────────────────
    addSpec() {
      const si = this.specifications.length;
      this.registerSpecListeners(si);
      this.specifications.push({
        groupOperator: "",
        qualificationCriteria: [],
        experienceCriteria: [],
        otherRequirements: [],
      });
    },

    removeSpec(si) {
      if (this.specifications.length > 1) {
        this.specifications.splice(si, 1);
      }
    },

    addQualCriterion(si) {
      const ci = this.specifications[si].qualificationCriteria.length;
      this.registerQualCritListeners(si, ci);
      this.specifications[si].qualificationCriteria.push({
        criterionOperator: "",
        qualificationLevel: "",
        qualificationName: "",
        nameKey: 0,
      });
    },

    removeQualCriterion(si, ci) {
      this.specifications[si].qualificationCriteria.splice(ci, 1);
    },

    addExpCriterion(si) {
      const ci = this.specifications[si].experienceCriteria.length;
      this.registerExpCritListeners(si, ci);
      this.specifications[si].experienceCriteria.push({
        criterionOperator: "",
        minimumYears: "",
        jobTitle: "",
      });
    },

    removeExpCriterion(si, ci) {
      this.specifications[si].experienceCriteria.splice(ci, 1);
    },

    addOtherReq(si) {
      const ri = this.specifications[si].otherRequirements.length;
      this.registerOtherReqListener(si, ri);
      this.specifications[si].otherRequirements.push("");
    },

    removeOtherReq(si, ri) {
      this.specifications[si].otherRequirements.splice(ri, 1);
    },

    // ── Convert this.specifications → FHIR extension array ───────────
    buildSpecFhir() {
      const COND_CS =
        "http://ihris.org/fhir/CodeSystem/conditional-operator-codesystem";

      return this.specifications
        .map((spec) => {
          const extension = [];

          const opCoding = (val) => {
            const c = this.parseCoding(val) || { system: COND_CS, code: val };
            if (!c.display) {
              c.display = c.code === "or" ? "OR" : "AND";
            }
            return c;
          };

          if (spec.groupOperator) {
            extension.push({
              url: "spec-group-operator",
              valueCoding: opCoding(spec.groupOperator),
            });
          }

          for (const qc of spec.qualificationCriteria) {
            const critExt = [];
            if (qc.criterionOperator) {
              critExt.push({
                url: "spec-criterion-operator",
                valueCoding: opCoding(qc.criterionOperator),
              });
            }
            if (qc.qualificationLevel) {
              critExt.push({
                url: "qualification-level",
                valueCoding: this.parseCoding(qc.qualificationLevel),
              });
            }
            if (qc.qualificationName) {
              critExt.push({
                url: "qualification-name",
                valueReference: {
                  reference: this.getRef(qc.qualificationName),
                },
              });
            }
            if (critExt.length) {
              extension.push({
                url: BASE_EXT + "spec-qualification-criterion",
                extension: critExt,
              });
            }
          }

          for (const ec of spec.experienceCriteria) {
            const critExt = [];
            if (ec.criterionOperator) {
              critExt.push({
                url: "spec-criterion-operator",
                valueCoding: opCoding(ec.criterionOperator),
              });
            }
            if (ec.minimumYears !== "" && ec.minimumYears != null) {
              critExt.push({
                url: "minimum-years",
                valuePositiveInt: Math.max(1, parseInt(ec.minimumYears) || 1),
              });
            }
            if (ec.jobTitle) {
              critExt.push({ url: "job-title", valueString: ec.jobTitle });
            }
            if (critExt.length) {
              extension.push({
                url: BASE_EXT + "spec-experience-criterion",
                extension: critExt,
              });
            }
          }

          for (const req of spec.otherRequirements) {
            if (req)
              extension.push({ url: "other-requirement", valueString: req });
          }

          return { url: BASE_EXT + "position-specification", extension };
        })
        .filter((s) => s.extension.length > 0);
    },

    // ── Submit ────────────────────────────────────────────────────────
    async submitForm() {
      this.$refs.form.validate();
      if (!this.valid) return;

      this.saving = true;
      try {
        this.fhir = {
          specifications: this.buildSpecFhir(),
        };
        if (this.editMode) {
          this.afterSaveMessage = "Position updated successfully.";
        } else {
          this.afterSaveMessage = "Position created successfully.";
        }
        await this.processFHIR();
        setTimeout(() => this.goBack(), 200);
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar(
          "Failed to save position. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },

    // ── Prefill (edit mode) ───────────────────────────────────────────
    prefillFromResource(resource) {
      const exts = resource.extension || [];
      const getStr = (suffix) => {
        const e = exts.find(
          (x) => x.url.endsWith("/" + suffix) || x.url === suffix,
        );
        return e ? e.valueString || "" : "";
      };
      const getCoding = (suffix) => {
        const e = exts.find(
          (x) => x.url.endsWith("/" + suffix) || x.url === suffix,
        );
        return e ? e.valueCoding || null : null;
      };
      const getRef = (suffix) => {
        const e = exts.find(
          (x) => x.url.endsWith("/" + suffix) || x.url === suffix,
        );
        return e ? e.valueReference || null : null;
      };
      const getInt = (suffix) => {
        const e = exts.find(
          (x) => x.url.endsWith("/" + suffix) || x.url === suffix,
        );
        return e != null && e.valueInteger != null ? e.valueInteger : "";
      };
      const allOf = (suffix) =>
        exts.filter((x) => x.url.endsWith("/" + suffix) || x.url === suffix);
      const subStr = (entry, url) => {
        const c = (entry.extension || []).find(
          (x) => x.url === url || x.url.endsWith("/" + url),
        );
        return c ? c.valueString || "" : "";
      };
      const subCoding = (entry, url) => {
        const c = (entry.extension || []).find(
          (x) => x.url === url || x.url.endsWith("/" + url),
        );
        return c ? c.valueCoding || null : null;
      };
      const subRef = (entry, url) => {
        const c = (entry.extension || []).find(
          (x) => x.url === url || x.url.endsWith("/" + url),
        );
        return c ? c.valueReference || null : null;
      };
      const subInt = (entry, url) => {
        const c = (entry.extension || []).find(
          (x) => x.url === url || x.url.endsWith("/" + url),
        );
        return c != null && c.valueInteger != null
          ? c.valueInteger
          : c?.valuePositiveInt ?? "";
      };

      this.form.name = getStr("ihris-basic-name");
      this.form.code = getStr("position-code");
      this.form.description = getStr("description");
      this.form.comments = getStr("comments");
      this.form.maximumPractitioners = getInt("maximum-practitioners");

      this.form.designation = getRef("designation");
      this.form.grade = getRef("salary-grade");
      this.form.facility = getRef("facility");

      this.form.department = getCoding("department").code;

      this.form.status = getCoding("position-status").code;

      // Parse specifications
      const specExts = allOf("position-specification");
      if (specExts.length) {
        this.specifications = specExts.map((specEntry, si) => {
          const groupOpCoding = subCoding(specEntry, "spec-group-operator");
          const groupOperator = groupOpCoding ? groupOpCoding.code || "" : "";

          const qualCritExts = (specEntry.extension || []).filter(
            (x) =>
              x.url.endsWith("/spec-qualification-criterion") ||
              x.url === BASE_EXT + "spec-qualification-criterion",
          );
          const qualificationCriteria = qualCritExts.map((qcEntry, ci) => {
            const opCoding = subCoding(qcEntry, "spec-criterion-operator");
            const lvCoding = subCoding(qcEntry, "qualification-level");
            const qnRef = subRef(qcEntry, "qualification-name");
            this.registerQualCritListeners(si, ci);
            return {
              criterionOperator: opCoding ? opCoding.code || "" : "",
              qualificationLevel: lvCoding ? lvCoding.code || "" : "",
              qualificationName: qnRef || "",
              nameKey: 0,
            };
          });

          const expCritExts = (specEntry.extension || []).filter(
            (x) =>
              x.url.endsWith("/spec-experience-criterion") ||
              x.url === BASE_EXT + "spec-experience-criterion",
          );
          const experienceCriteria = expCritExts.map((ecEntry, ci) => {
            const opCoding = subCoding(ecEntry, "spec-criterion-operator");
            this.registerExpCritListeners(si, ci);
            return {
              criterionOperator: opCoding ? opCoding.code || "" : "",
              minimumYears: subInt(ecEntry, "minimum-years"),
              jobTitle: subStr(ecEntry, "job-title"),
            };
          });

          const otherRequirements = (specEntry.extension || [])
            .filter((x) => x.url === "other-requirement")
            .map((x) => x.valueString || "");
          otherRequirements.forEach((_, ri) =>
            this.registerOtherReqListener(si, ri),
          );

          return {
            groupOperator,
            qualificationCriteria,
            experienceCriteria,
            otherRequirements,
          };
        });
      }
    },
  },

  components: {
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-reference": () => import("@/components/fhir/fhir-reference"),
    "fhir-integer": () => import("@/components/fhir/fhir-integer"),
  },

  created() {
    // Register spec[0] listeners (initial spec)
    this.registerSpecListeners(0);

    // ── Load resource in edit mode ────────────────────────────────────
    const id = this.queries && this.queries.id;
    if (id) {
      this.fhirId = id;
      this.prefillReady = false;
      fetch(`/fhir/Basic/${id}`)
        .then((r) => r.json())
        .then((data) => {
          const resource =
            data.resourceType === "Bundle" ? data.entry?.[0]?.resource : data;
          if (resource) this.prefillFromResource(resource);
        })
        .catch((e) => console.error("prefill error:", e))
        .finally(() => {
          this.prefillReady = true;
        });
    }
  },
};
</script>

